<?php declare(strict_types=1);$labels=['ACTIVITY'=>'Kegiatan Lapangan','UPDATE'=>'Update Program','MEDIA'=>'Liputan Media','AWARD'=>'Penghargaan'];?>
<section class="admin-page-toolbar"><p>Kelola artikel, penghargaan, liputan media, sampul, dan foto dokumentasi.</p><a class="button-primary button-link" href="<?=url('/admin/berita/tambah')?>">+ Tambah berita</a></section>
<?php if($posts===[]):?><section class="card-surface empty-state"><h2>Belum ada berita</h2><p>Tambahkan artikel atau kegiatan pertama.</p><a class="button-primary button-link" href="<?=url('/admin/berita/tambah')?>">Tambah berita</a></section><?php else:?><div class="card-surface table-scroll"><table class="admin-table"><thead><tr><th>Judul</th><th>Kategori</th><th>Status</th><th>Terbit</th><th>Foto</th><th>Aksi</th></tr></thead><tbody><?php foreach($posts as $post):?><tr><td><strong><?=e($post['title'])?></strong><small>/berita/<?=e($post['slug'])?></small></td><td><?=e($labels[$post['category']]??$post['category'])?></td><td><span class="status-pill <?=((int)$post['is_published']===1?'status-open':'status-closed')?>"><?=((int)$post['is_published']===1?'Terbit':'Draf')?></span></td><td><?=e(date('d M Y H:i',strtotime($post['published_at'])))?></td><td><?= (int)$post['photo_count']?></td><td class="table-actions"><a href="<?=url('/admin/berita/'.$post['id'].'/ubah')?>">Ubah</a><form method="post" action="<?=url('/admin/berita/'.$post['id'].'/hapus')?>" data-confirm="Hapus berita dan semua fotonya?"><?=csrf_field()?><button class="text-danger" type="submit">Hapus</button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
